import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, smoothstep, distance, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

function hexToVec3(hex) {
  const c = parseInt(hex.replace('#', ''), 16);
  const r = ((c >> 16) & 255) / 255;
  const g = ((c >> 8) & 255) / 255;
  const b = (c & 255) / 255;
  return vec3(r, g, b);
}

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, PointLight, Box3, Vector3, Color, DoubleSide } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'hub-features-thumb';

  const disposables = [];
  const timelines = [];
  const primitiveHandles = [];
  let disposed = false;

  // ---------------------------------------------------------------
  // Card backdrop (engineered vertical gradient: ink -> surface)
  // ---------------------------------------------------------------
  const cardW = 2.4;
  const cardH = 2.9;

  const backdropGeo = new PlaneGeometry(cardW, cardH, 1, 1);
  const backdropMat = new MeshStandardNodeMaterial({ roughness: 0.6, metalness: 0.15, side: DoubleSide });
  backdropMat.colorNode = mix(hexToVec3(colors.surface), hexToVec3(colors.ink), uv().y);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -0.06);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------------------------------------------------------------
  // Caption strip (bottom, solid ink) + thin accent separator line
  // ---------------------------------------------------------------
  const stripH = 0.5;
  const stripGeo = new PlaneGeometry(cardW, stripH, 1, 1);
  const stripMat = new MeshStandardNodeMaterial({ roughness: 0.55, metalness: 0.3, side: DoubleSide });
  stripMat.colorNode = hexToVec3(colors.ink);
  const strip = new Mesh(stripGeo, stripMat);
  strip.position.set(0, -cardH / 2 + stripH / 2, -0.03);
  root.add(strip);
  disposables.push(stripGeo, stripMat);

  const lineGeo = new PlaneGeometry(cardW, 0.018, 1, 1);
  const lineMat = new MeshStandardNodeMaterial({ roughness: 0.5, metalness: 0.35, side: DoubleSide });
  lineMat.colorNode = hexToVec3(colors.accent);
  const line = new Mesh(lineGeo, lineMat);
  line.position.set(0, -cardH / 2 + stripH, -0.02);
  root.add(line);
  disposables.push(lineGeo, lineMat);

  // ---------------------------------------------------------------
  // Contact shadow under the subject (radial falloff plane)
  // ---------------------------------------------------------------
  const shadowRadius = 0.85;
  const shadowGeo = new PlaneGeometry(shadowRadius * 2, shadowRadius * 2, 1, 1);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const centeredUv = uv().sub(vec2(0.5, 0.5)).mul(2.0);
  const d = distance(centeredUv, vec2(0.0, 0.0));
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = smoothstep(1.0, 0.0, d).mul(0.5);
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -cardH / 2 + stripH + 0.1, 0.02);
  root.add(shadowMesh);
  disposables.push(shadowGeo, shadowMat);

  // ---------------------------------------------------------------
  // Local accent rim light (backlight for the machined-metal gear)
  // ---------------------------------------------------------------
  const rimLight = new PointLight(new Color(colors.accent), 0.8, 4, 2);
  rimLight.position.set(-0.6, 0.4, 1.4);
  root.add(rimLight);

  // ---------------------------------------------------------------
  // Subject: GLB gear mesh, loaded async, normalized + centered
  // ---------------------------------------------------------------
  const subjectGroup = new Group();
  subjectGroup.position.set(0, 0.28, 0.08);
  root.add(subjectGroup);

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      if (disposed) return;
      const scene = gltf.scene ?? gltf.scenes?.[0];
      if (!scene) return;

      const box = new Box3().setFromObject(scene);
      const size = new Vector3();
      box.getSize(size);
      const maxDim = Math.max(size.x, size.y, size.z, 0.0001);
      const targetSize = 1.35;
      const scale = targetSize / maxDim;
      scene.scale.setScalar(scale);

      const center = new Vector3();
      box.getCenter(center);
      scene.position.sub(center.multiplyScalar(scale));

      subjectGroup.add(scene);
    }).catch(() => {});
  }

  // ---------------------------------------------------------------
  // Cinematic primitives
  // ---------------------------------------------------------------
  const primitiveConfigs = config.cinematicPrimitives ?? [];
  for (const p of primitiveConfigs) {
    const fn = ctx.primitives?.[p.name];
    if (!fn) continue;
    const target = p.name === 'magnetic-cursor' ? root : root;
    const handle = fn(target, p.params ?? {});
    if (handle) primitiveHandles.push(handle);
  }

  // ---------------------------------------------------------------
  // Weighted-settle entrance
  // ---------------------------------------------------------------
  const baseY = 0;
  root.scale.setScalar(0.96);
  root.position.y = baseY - 0.3;

  const entranceTl = gsap.timeline();
  entranceTl.to(root.position, { y: baseY, duration: 0.7, ease: 'power3.out' }, 0);
  entranceTl.to(root.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' }, 0);
  timelines.push(entranceTl);

  // ---------------------------------------------------------------
  // Interaction handlers
  // ---------------------------------------------------------------
  let hovering = false;

  const hoverInTl = () => {
    const tl = gsap.timeline();
    tl.to(root.position, { y: baseY + 0.15, duration: 0.3, ease: 'power2.out' }, 0);
    tl.to(root.scale, { x: 1.02, y: 1.02, z: 1.02, duration: 0.3, ease: 'power2.out' }, 0);
    timelines.push(tl);
    return tl;
  };

  const hoverOutTl = () => {
    const tl = gsap.timeline();
    tl.to(root.position, { y: baseY, duration: 0.3, ease: 'power2.out' }, 0);
    tl.to(root.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.3, ease: 'power2.out' }, 0);
    timelines.push(tl);
    return tl;
  };

  const onPointerOver = () => {
    if (hovering) return;
    hovering = true;
    hoverInTl();
  };

  const onPointerOut = () => {
    if (!hovering) return;
    hovering = false;
    hoverOutTl();
  };

  const onPointerDown = () => {
    const tl = gsap.timeline();
    tl.to(root.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
    tl.to(root.scale, { x: hovering ? 1.02 : 1.0, y: hovering ? 1.02 : 1.0, z: hovering ? 1.02 : 1.0, duration: 0.18, ease: 'power2.out' });
    timelines.push(tl);
  };

  const onClick = () => {
    ctx.emit('hub-features.select', { nodeId: config.id ?? 'hub-features-thumb' });
  };

  root.userData.handlers = {
    onPointerOver,
    onPointerOut,
    onPointerDown,
    onClick,
  };

  // ---------------------------------------------------------------
  // Cleanup
  // ---------------------------------------------------------------
  root.userData.cleanup = () => {
    disposed = true;

    for (const tl of timelines) {
      tl.kill();
    }
    timelines.length = 0;

    for (const handle of primitiveHandles) {
      handle.timeline?.kill?.();
      handle.cleanup?.();
    }
    primitiveHandles.length = 0;

    for (const item of disposables) {
      item.dispose?.();
    }
    disposables.length = 0;

    root.remove(rimLight);
    root.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose?.();
      if (obj.material) {
        const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
        for (const m of mats) {
          m.dispose?.();
        }
      }
    });
  };

  return root;
}
